#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_1 2
#define GPIO_2 3
#define CONSUMER "digital_output"

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_1);
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line1, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line1");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output line2");
        goto cleanup;
    }

    while (keep_running) {
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value line1");
            break;
        }
        printf("GPIO 2: HIGH\n");
        fflush(stdout);

        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value line2");
            break;
        }
        printf("GPIO 3: LOW\n");
        fflush(stdout);

        sleep(0.1);
    }

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 2
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value LOW */
    if (gpiod_line_request_output(line, "gpio_output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("GPIO %d output started. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        printf("GPIO %d: %d\n", GPIO_LINE, val);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release the line and close the chip */
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("GPIO %d output stopped.\n", GPIO_LINE);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 3.3
#define SAMPLE_INTERVAL_US 500000

static int i2c_fd = -1;

static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to ADS1115 reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t config = 0x8000; // AIN0 single-ended, PGA 4.096V, single-shot, 128 SPS
    if (ads1115_write_reg(fd, CONFIG_REG, config) < 0) {
        return -1;
    }
    return 0;
}

static int ads1115_read_channel(int fd, int channel, float *voltage) {
    uint16_t config = 0x4000 | (channel << 12); // Single-shot, AIN0, PGA 4.096V
    if (ads1115_write_reg(fd, CONFIG_REG, config) < 0) {
        return -1;
    }
    usleep(10000); // Wait for conversion
    uint16_t raw;
    if (ads1115_read_reg(fd, CONVERSION_REG, &raw) < 0) {
        return -1;
    }
    *voltage = (raw * REF_VOLTAGE) / 32768.0;
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing ADS1115\n");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        float voltage;
        if (ads1115_read_channel(i2c_fd, 0, &voltage) == 0) {
            printf("Voltage: %.3f V\n", voltage);
        } else {
            fprintf(stderr, "Error reading channel 0\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MLX90614_ADDR 0x5A
#define I2C_DEVICE "/dev/i2c-1"
#define NUM_READINGS 2

static int fd = -1;

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MLX90614_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90614 reader started. Press Ctrl+C to exit.\n");

    while (1) {
        uint16_t temp1, temp2;
        if (i2c_read_word(fd, 0x04, &temp1) != 0) {
            fprintf(stderr, "Error reading temperature 1, exiting.\n");
            break;
        }
        if (i2c_read_word(fd, 0x06, &temp2) != 0) {
            fprintf(stderr, "Error reading temperature 2, exiting.\n");
            break;
        }

        printf("Temperature 1: %.2f C, Temperature 2: %.2f C\n", temp1 / 100.0, temp2 / 100.0);
        sleep(5);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("I2C connection closed.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_4 4
#define GPIO_17 17

static struct gpiod_line *line4 = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_chip *chip = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line4) {
        gpiod_line_release(line4);
        line4 = NULL;
    }
    if (line17) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        perror("gpiod_chip_get_line GPIO 4");
        gpiod_chip_close(chip);
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line GPIO 17");
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line4, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output GPIO 4");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line17, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output GPIO 17");
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Digital output on GPIO 4 and GPIO 17. Press Ctrl+C to exit.\n");

    while (1) {
        gpiod_line_set_value(line4, 1);
        gpiod_line_set_value(line17, 1);
        printf("GPIO 4: HIGH, GPIO 17: HIGH\n");
        sleep(1);
        gpiod_line_set_value(line4, 0);
        gpiod_line_set_value(line17, 0);
        printf("GPIO 4: LOW, GPIO 17: LOW\n");
        sleep(1);
    }

    cleanup_and_exit(0);
    return 0;
}

