#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_17 17
#define GPIO_18 18

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL, *line18 = NULL;
    int ret = EXIT_FAILURE;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line17, "gpio17", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, "gpio18", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    printf("GPIO 17 and GPIO 18 set as outputs. Press Ctrl+C to exit.\n");

    while (1) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0 || val18 < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("GPIO 17: %d, GPIO 18: %d\n", val17, val18);
        fflush(stdout);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or not running?)\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int state = (rand() % 2) ? 1 : 0;
        if (gpioPWM(PWM_PIN, state) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", PWM_PIN);
            break;
        }
        printf("PWM state: %d\n", state);
        fflush(stdout);
        usleep(LOOP_DELAY_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
