#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define CHIP_NAME   "gpiochip0"
#define MAX_RETRIES 3
#define POLL_INTERVAL_MS 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(struct gpiod_line *trig) {
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trig HIGH)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig LOW)");
        return -1;
    }
    return 0;
}

static int read_echo(struct gpiod_line *echo) {
    int val = gpiod_line_get_value(echo);
    if (val < 0) {
        perror("gpiod_line_get_value(echo)");
        return -1;
    }
    return val;
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (trigger_sensor(trig) < 0) return -1.0f;
        usleep(50000);
        int echo_val = read_echo(echo);
        if (echo_val < 0) return -1.0f;
        if (echo_val == 0) return -1.0f;
        int timeout = 0;
        while (gpiod_line_get_value(echo) == 1 && timeout < 200000) {
            usleep(1);
            timeout++;
        }
        if (timeout >= 200000) return -1.0f;
        int end_val = read_echo(echo);
        if (end_val < 0) return -1.0f;
        if (end_val == 0) return -1.0f;
        long long elapsed_us = (long long)timeout * 1000;
        float distance = (float)elapsed_us / 2.0f / 10000.0f;
        if (distance < 2.0f || distance > 400.0f) return -1.0f;
        return distance;
    }
    return -1.0f;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = 1;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        float distance = measure_distance(trig, echo);
        if (distance < 0.0f) {
            fprintf(stderr, "Error: HC-SR04 measurement failed after retries.\n");
            break;
        }
        printf("Distance: %.2f cm\n", distance);
        sleep(60);
    }

    ret = 0;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x28
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 3.3
#define SAMPLE_INTERVAL 5

static int i2c_fd = -1;

static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to ADS1115 reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t config = 0x8000; // AIN0 single-ended, PGA 4.096V, single-shot, 128 SPS
    if (ads1115_write_reg(fd, CONFIG_REG, config) < 0) {
        return -1;
    }
    return 0;
}

static int ads1115_read_channel(int fd, int channel, float *voltage) {
    uint16_t config = 0x4000 | (channel << 12); // Single-shot, AIN0, PGA 4.096V
    uint16_t raw;
    if (ads1115_write_reg(fd, CONFIG_REG, config) < 0) {
        return -1;
    }
    usleep(10000); // Wait for conversion (128 SPS -> ~7.8ms, round up)
    if (ads1115_read_reg(fd, CONVERSION_REG, &raw) < 0) {
        return -1;
    }
    *voltage = (raw * REF_VOLTAGE) / 32768.0;
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing ADS1115 at 0x%02X\n", ADS1115_ADDR);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        float voltage;
        if (ads1115_read_channel(i2c_fd, 0, &voltage) == 0) {
            printf("Voltage: %.3f V\n", voltage);
        } else {
            fprintf(stderr, "Error reading channel 0\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    close(i2c_fd);
    return 0;
}

