#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 18
#define NUM_CYCLES 3
#define CYCLE_DELAY 2

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CYCLES; i++) {
        chip = gpiod_chip_open(GPIO_CHIP);
        if (!chip) {
            fprintf(stderr, "Error: Failed to open GPIO chip %s\n", GPIO_CHIP);
            goto cleanup;
        }

        line = gpiod_chip_get_line(chip, GPIO_LINE);
        if (!line) {
            fprintf(stderr, "Error: Failed to get GPIO line %d\n", GPIO_LINE);
            goto cleanup;
        }

        int val = (i % 2 == 0) ? 1 : 0;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to set GPIO line %d to %d\n", GPIO_LINE, val);
            goto cleanup;
        }

        printf("Cycle %d: GPIO %d set to %d\n", i + 1, GPIO_LINE, val);
        sleep(CYCLE_DELAY);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to reset GPIO line %d\n", GPIO_LINE);
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

int main() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    // Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous
    uint16_t config = 0x4000 | 0x0200 | 0x0100 | 0x0080 | 0x0000;
    uint8_t config_buf[3];
    config_buf[0] = CONFIG_REG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (write(fd, config_buf, 3) != 3) {
        fprintf(stderr, "Failed to write config: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Wait for first conversion (128 SPS -> ~7.8ms, use 10ms)
    usleep(10000);

    uint8_t reg = CONVERSION_REG;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to set conversion register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read conversion: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    uint16_t raw = (buf[0] << 8) | buf[1];
    printf("ADS1115 Conversion: %u\n", raw);
    close(fd);
    return 0;
}

