#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 3.3
#define SAMPLE_COUNT 3

static int i2c_fd = -1;

static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to ADS1115 reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t config = 0x8000; // AIN0 single-ended, PGA 4.096V, single-shot, 128 SPS
    if (ads1115_write_reg(fd, CONFIG_REG, config) < 0) {
        return -1;
    }
    return 0;
}

static int ads1115_read_channel(int fd, int channel, float *voltage) {
    uint16_t config = 0x4000 | (channel << 12); // Single-shot, AIN0, PGA 4.096V
    if (ads1115_write_reg(fd, CONFIG_REG, config) < 0) {
        return -1;
    }
    uint16_t raw;
    if (ads1115_read_reg(fd, CONVERSION_REG, &raw) < 0) {
        return -1;
    }
    *voltage = (raw * REF_VOLTAGE) / 32768.0;
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing ADS1115\n");
        close(i2c_fd);
        return 1;
    }

    for (int i = 0; i < SAMPLE_COUNT; i++) {
        float voltage;
        if (ads1115_read_channel(i2c_fd, 0, &voltage) < 0) {
            fprintf(stderr, "Error reading channel %d\n", i);
            close(i2c_fd);
            return 1;
        }
        printf("Channel %d: %.3f V\n", i, voltage);
        sleep(1);
    }

    close(i2c_fd);
    return 0;
}

