#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"
#define MAX_RETRIES 3
#define TIMEOUT_US  1000000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_pulse(struct gpiod_line *trig) {
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    return 0;
}

static int echo_wait(struct gpiod_line *echo, struct timespec *start) {
    int val;
    struct timespec now;
    long elapsed;

    while (1) {
        val = gpiod_line_get_value(echo);
        if (val < 0) return -1;
        if (val == 1) {
            clock_gettime(CLOCK_MONOTONIC, &now);
            elapsed = (now.tv_sec - start->tv_sec) * 1000000L +
                      (now.tv_nsec - start->tv_nsec) / 1000L;
            if (elapsed > TIMEOUT_US) return 0;
        }
        if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) return -1;
    }
}

static int read_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec start, end;
    int ret;

    if (trigger_pulse(trig) < 0) return -1;
    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) return -1;

    ret = echo_wait(echo, &start);
    if (ret < 0) return -1;

    if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) return -1;
    return (int)((end.tv_sec - start.tv_sec) * 1000000L +
                 (end.tv_nsec - start.tv_nsec) / 1000L);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        int dist = -1;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            dist = read_distance(trig, echo);
            if (dist >= 0) {
                printf("Distance: %d mm\n", dist);
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d failed\n", attempt + 1);
            usleep(100000);
        }

        if (!ok) {
            fprintf(stderr, "Max retries reached. Exiting.\n");
            break;
        }

        sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

