#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define DHT11_MAX_RETRIES 5
#define DHT11_TIMEOUT_MS 1000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

static int wait_for_line(struct gpiod_line *line, int val, int timeout_ms) {
    int elapsed = 0;
    while (elapsed < timeout_ms) {
        int v = gpiod_line_get_value(line);
        if (v < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (v == val) return 0;
        usleep(1000);
        elapsed += 1000;
    }
    return -1;
}

static int read_dht11(struct gpiod_line *line, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int i;

    if (gpiod_line_request_output(line, "dht11", 1) < 0) {
        fprintf(stderr, "Failed to request output: %s\n", strerror(errno));
        return -1;
    }

    usleep(100000);

    if (gpiod_line_request_input(line, "dht11") < 0) {
        fprintf(stderr, "Failed to request input: %s\n", strerror(errno));
        return -1;
    }

    if (wait_for_line(line, 0, DHT11_TIMEOUT_MS) < 0) return -1;
    if (wait_for_line(line, 1, DHT11_TIMEOUT_MS) < 0) return -1;
    if (wait_for_line(line, 0, DHT11_TIMEOUT_MS) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_line(line, 1, DHT11_TIMEOUT_MS) < 0) return -1;
        if (wait_for_line(line, 0, DHT11_TIMEOUT_MS) < 0) return -1;

        int bit = gpiod_line_get_value(line);
        if (bit < 0) return -1;
        data[i / 8] <<= 1;
        if (bit) data[i / 8] |= 1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0f;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", DHT11_PIN, strerror(errno));
        goto cleanup;
    }

    for (int attempt = 0; attempt < DHT11_MAX_RETRIES; attempt++) {
        float temp, hum;
        if (read_dht11(line, &temp, &hum) == 0) {
            printf("DHT11: Temperature = %.1f C, Humidity = %.1f %%\n", temp, hum);
            ret = 0;
            break;
        }
        fprintf(stderr, "DHT11 read failed (attempt %d/%d)\n", attempt + 1, DHT11_MAX_RETRIES);
        usleep(1000000);
    }

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

