        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "gpio8_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_LINE, val);
        fflush(stdout);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    printf("\nGPIO released. Exiting.\n");
    return EXIT_SUCCESS;
}

