#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define OPT3001_ADDR 0x44
#define I2C_DEVICE "/dev/i2c-1"

int main() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", OPT3001_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t cmd[2] = {0x80, 0x00};
    uint8_t buf[3];

    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write to OPT3001: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    usleep(100000);

    if (read(fd, buf, 3) != 3) {
        fprintf(stderr, "Failed to read from OPT3001: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t result = raw & 0x07FF;

    printf("OPT3001 measurement: %u\n", result);
    close(fd);
    return 0;
}

