        if (val < 0) {
            fprintf(stderr, "Failed to set GPIO line %d high\n", GPIO_LINE);
            goto cleanup;
        }

        printf("Cycle %d: GPIO %d set high\n", i + 1, GPIO_LINE);
        fflush(stdout);

        sleep(CYCLE_INTERVAL);

        val = gpiod_line_set_value(line, 0);
        if (val < 0) {
            fprintf(stderr, "Failed to set GPIO line %d low\n", GPIO_LINE);
            goto cleanup;
        }

