#include <errno.h>
#include <signal.h>
#include <time.h>

#define W1_BUS_4 "/sys/bus/w1/devices/28-000000000000"
#define W1_BUS_17 "/sys/bus/w1/devices/28-000000000001"
#define W1_BUS_18 "/sys/bus/w1/devices/28-000000000002"
#define W1_DIR "/sys/bus/w1/devices/28-000000000000/w1_slave"
#define W1_DIR_17 "/sys/bus/w1/devices/28-000000000001/w1_slave"
#define W1_DIR_18 "/sys/bus/w1/devices/28-000000000002/w1_slave"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_w1(const char *path, float *temp) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    char line1[256], line2[256];
    if (!fgets(line1, sizeof(line1), fp) || !fgets(line2, sizeof(line2), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "Device not responding on %s\n", path);
        return -1;
    }
    char *t = strstr(line1, "t=");
    if (!t) {
        fprintf(stderr, "Temperature not found on %s\n", path);
        return -1;
    }
    long millideg = strtol(t + 2, NULL, 10);
    *temp = millideg / 1000.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting DS18B20 readings on GPIO 4, 17, 18...\n");

    while (running) {
        float t4 = 0, t17 = 0, t18 = 0;
        int ok = 1;
        if (read_w1(W1_DIR, &t4)) ok = 0;
        if (read_w1(W1_DIR_17, &t17)) ok = 0;
        if (read_w1(W1_DIR_18, &t18)) ok = 0;
        if (ok) {
            printf("GPIO 4: %.1f C, GPIO 17: %.1f C, GPIO 18: %.1f C\n", t4, t17, t18);
        } else {
            fprintf(stderr, "Error reading temperature. Exiting.\n");
            break;
        }
        sleep(5);
    }

    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define HTU21D_ADDR 0x40
#define I2C_DEVICE "/dev/i2c-1"
#define READ_INTERVAL 60

static int i2c_fd = -1;

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temperature) {
    uint8_t data[3];
    if (i2c_write_byte(fd, 0x2E) < 0) return -1;
    usleep(50000);
    if (i2c_read_bytes(fd, data, 3) < 0) return -1;

    uint16_t raw_temp = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_hum = ((uint16_t)data[2] << 8) | data[3];

    if (raw_temp & 0x8000) {
        *temperature = -((float)(raw_temp & 0x7FFF)) / 160.0;
    } else {
        *temperature = (float)raw_temp / 160.0;
    }
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    uint8_t data[3];
    if (i2c_write_byte(fd, 0x2F) < 0) return -1;
    usleep(50000);
    if (i2c_read_bytes(fd, data, 3) < 0) return -1;

    uint16_t raw_hum = ((uint16_t)data[0] << 8) | data[1];
    if (raw_hum & 0x8000) {
        *humidity = -((float)(raw_hum & 0x7FFF)) / 16384.0;
    } else {
        *humidity = (float)raw_hum / 16384.0;
    }
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (1) {
        float temperature, humidity;
        int ret = 0;

        if (read_temperature(i2c_fd, &temperature) < 0) {
            fprintf(stderr, "Temperature read failed\n");
            ret = 1;
        } else if (read_humidity(i2c_fd, &humidity) < 0) {
            fprintf(stderr, "Humidity read failed\n");
            ret = 1;
        } else {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        }

        if (ret) break;

        for (int i = 0; i < READ_INTERVAL && !ret; i++) {
            sleep(1);
        }
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return ret;
}

