void cleanup(int signum) {
    (void)signum;
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Set data format register to 0x0B (full resolution, +/- 3.9g)
    if (write(i2c_fd, (uint8_t[]){ADXL345_DATA_FORMAT, 0x0B}, 2) != 2) {
        perror("Failed to write data format register");
        close(i2c_fd);
        return 1;
    }

    // Enable measurement by setting POWER_CTL bit
    if (write(i2c_fd, (uint8_t[]){ADXL345_POWER_CTL, 0x08}, 2) != 2) {
        perror("Failed to write POWER_CTL register");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint8_t reg = ADXL345_DATAX0;
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to set data register pointer");
            close(i2c_fd);
            return 1;
        }

        uint8_t buf[6];
        if (read(i2c_fd, buf, 6) != 6) {
            perror("Failed to read 6 bytes of data");
            close(i2c_fd);
            return 1;
        }

        // Combine low and high bytes (little-endian)
        int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
        int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
        int16_t z = (int16_t)((buf[5] << 8) | buf[4]);

        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        fflush(stdout);

        usleep(100000); // 0.1 seconds
    }

    // Unreachable, but for completeness:
    close(i2c_fd);
    return 0;
}

