static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int i, j;
    int laststate = 1;
    int counter = 0;
    int jcounter = 0;
    struct timespec ts_start, ts_end;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    gpiod_line_set_value(line, 1);
    usleep(100000);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(40);
    gpiod_line_set_value(line, 0);

    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    for (i = 0; i < 85; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == laststate) {
            counter++;
            usleep(1);
            if (counter == 255) return -2;
        }
        laststate = gpiod_line_get_value(line);

        for (j = 0; j < 8; j++) {
            if (counter & (1 << j)) {
                data[jcounter / 8] <<= 1;
                if (i == 3 && j == 4) data[jcounter / 8] |= 1;
            }
            counter = (counter + 1) & 255;
        }
        jcounter++;
        if (i == 3 && j == 4) break;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -3;

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
