#define I2C_BUS "/dev/i2c-1"
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64
#define SSD1306_PAGES (SSD1306_HEIGHT / 8)

static int fd = -1;

static void cleanup(int signum) {
    (void)signum;
    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
    exit(0);
}

static int ssd1306_send_command(uint8_t cmd) {
    uint8_t buf[2] = {0x00, cmd};
    if (write(fd, buf, 2) != 2) {
        perror("ssd1306_send_command: write");
        return -1;
    }
    return 0;
}

static int ssd1306_send_data(const uint8_t *data, size_t len) {
    if (write(fd, data, len) != (ssize_t)len) {
        perror("ssd1306_send_data: write");
        return -1;
    }
    return 0;
}

static int ssd1306_init(void) {
    if (ssd1306_send_command(0xAE) < 0) return -1;
    if (ssd1306_send_command(0xD5) < 0) return -1;
    if (ssd1306_send_command(0x80) < 0) return -1;
    if (ssd1306_send_command(0xA8) < 0) return -1;
    if (ssd1306_send_command(0x3F) < 0) return -1;
    if (ssd1306_send_command(0xD3) < 0) return -1;
    if (ssd1306_send_command(0x00) < 0) return -1;
    if (ssd1306_send_command(0x40) < 0) return -1;
    if (ssd1306_send_command(0x8D) < 0) return -1;
    if (ssd1306_send_command(0x14) < 0) return -1;
    if (ssd1306_send_command(0x20) < 0) return -1;
    if (ssd1306_send_command(0x00) < 0) return -1;
    if (ssd1306_send_command(0xA1) < 0) return -1;
    if (ssd1306_send_command(0xC8) < 0) return -1;
    if (ssd1306_send_command(0xA4) < 0) return -1;
    if (ssd1306_send_command(0xA6) < 0) return -1;
    if (ssd1306_send_command(0xAF) < 0) return -1;
    return 0;
}

static int ssd1306_clear(void) {
    uint8_t buf[SSD1306_WIDTH + 1];
    buf[0] = 0x00;
    for (int i = 0; i < SSD1306_WIDTH; i++) {
        buf[i + 1] = 0x00;
    }
    return ssd1306_send_data(buf, SSD1306_WIDTH + 1);
}

static int ssd1306_set_cursor(int col, int row) {
    if (row < 0 || row >= SSD1306_HEIGHT) return -1;
    if (col < 0 || col >= SSD1306_WIDTH) return -1;
    uint8_t buf[2];
    buf[0] = 0xB0 | (row / 8);
    buf[1] = 0x00 | (col & 0x0F);
    return ssd1306_send_data(buf, 2);
}

static int ssd1306_write_value(int col, int row, int value) {
    if (value < 0 || value > 15) return -1;
    uint8_t buf[3];
    buf[0] = 0xB0 | (row / 8);
    buf[1] = 0x00 | (col & 0x0F);
    buf[2] = (uint8_t)value;
    return ssd1306_send_data(buf, 3);
