static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, BME280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error: Failed to read BME280 ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Error: Invalid BME280 ID: 0x%02X (expected 0x60)\n", id);
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset BME280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    if (i2c_write_reg8(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set humidity oversampling: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error: Failed to set config: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to set control measurement: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bme280_read_data(int fd, float *temperature, float *humidity, float *pressure) {
    uint8_t data[8];
    if (i2c_read_burst(fd, BME280_REG_DATA, data, 8) < 0) {
        fprintf(stderr, "Error: Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    int32_t raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_humidity = (data[6] << 8) | data[7];

    *pressure = (float)raw_pressure / 100.0;
    *temperature = (float)raw_temperature / 100.0;
    *humidity = (float)raw_humidity / 1024.0;

    return 0;
}

int main(void) {
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bme280_init(fd) < 0) {
        fprintf(stderr, "Error: BME280 initialization failed.\n");
        close(fd);
        return 1;
    }

    printf("BME280 initialized successfully.\n");

    while (1) {
        float temperature, humidity, pressure;
        if (bme280_read_data(fd, &temperature, &humidity, &pressure) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%RH, Pressure: %.2f Pa\n", temperature, humidity, pressure);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }
        sleep(5);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 3.3
#define SAMPLE_INTERVAL_US 200000

static int i2c_fd = -1;

static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to ADS1115 reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t config = 0x8000; // AIN0 single-ended, PGA 4.096V, single-shot, 128 SPS
    if (ads1115_write_reg(fd, CONFIG_REG, config) < 0) {
        return -1;
    }
    return 0;
}

static int ads1115_read_channel(int fd, int channel, float *voltage) {
    uint16_t config = 0x4000 | (channel << 12); // Single-shot, AIN0, PGA 4.096V
    if (ads1115_write_reg(fd, CONFIG_REG, config) < 0) {
        return -1;
    }
    usleep(10000); // Wait for conversion
    uint16_t raw;
    if (ads1115_read_reg(fd, CONVERSION_REG, &raw) < 0) {
        return -1;
    }
    *voltage = (raw * REF_VOLTAGE) / 32768.0;
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing ADS1115 at 0x%02X\n", ADS1115_ADDR);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        float voltage;
        if (ads1115_read_channel(i2c_fd, 0, &voltage) == 0) {
            printf("Voltage: %.3f V\n", voltage);
        } else {
            fprintf(stderr, "Error reading channel 0\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 4
#define POLL_INTERVAL_SEC 60

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (chip == NULL) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "gpio_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d on %s set as output. Press Ctrl+C to exit.\n", GPIO_LINE, GPIO_CHIP);

    /* Main loop */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_LINE, val);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

