#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

int main(void) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Wake up MPU6050 (clear sleep bit)
    uint8_t wake_cmd = 0x00;
    if (write(fd, &wake_cmd, 1) != 1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(100000); // 100ms stabilization

    while (1) {
        uint8_t buf[6];
        if (read(fd, buf, 6) != 6) {
            fprintf(stderr, "Error reading from MPU6050: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
        fflush(stdout);

        usleep(10000); // 10ms
    }

    close(fd);
    return EXIT_SUCCESS;
}

