    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line14 = gpiod_chip_get_line(chip, GPIO_14);
    if (!line14) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_14, strerror(errno));
        goto cleanup;
    }
    line15 = gpiod_chip_get_line(chip, GPIO_15);
    if (!line15) {
