#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <syslog.h>
#include <syslog.h>
#include <MQTTClient.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "rpi_sensor"
#define MQTT_KEEPALIVE 60
#define MQTT_QOS 1
#define MQTT_TIMEOUT 1000
#define READ_INTERVAL_SEC 0.01
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static MQTTClient client;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_mqtt(void) {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = MQTT_KEEPALIVE;
    conn_opts.cleansession = 1;
    conn_opts.connectTimeout = MQTT_TIMEOUT;

    if (MQTTClient_create(&client, MQTT_HOST, MQTT_PORT, MQTT_CLIENT_ID,
                          MQTT_CLIENT_ID, NULL, &conn_opts) != MQTTClient_create_OK) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "MQTT client created successfully");
    return 0;
}

static int publish_sensor_data(float temperature, float humidity) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_data_ptr payload = malloc(1 * sizeof(char));
    if (!payload) {
        syslog(LOG_ERR, "Failed to allocate payload: %s", strerror(errno));
        return -1;
    }
    payload[0] = 't';
    pubmsg.payload = payload;
    pubmsg.payloadlen = 1;
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = 0;
    pubmsg.topic = MQTT_TOPIC;
    pubmsg.timeOut = MQTT_TIMEOUT;

    if (MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, NULL) != MQTTClient_publishMessage_OK) {
        syslog(LOG_ERR, "Failed to publish message: %s", strerror(errno));
        free(payload);
        return -1;
    }
    syslog(LOG_INFO, "Published: %s", MQTT_TOPIC);
    free(payload);
    return 0;
}

static int read_sensor_data(float *temperature, float *humidity) {
    *temperature = 25.0f;
    *humidity = 50.0f;
    return 0;
}

static void cleanup(void) {
    if (client) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        syslog(LOG_INFO, "MQTT client destroyed");
    }
    pthread_mutex_destroy(&mutex);
    closelog();
}

int main(void) {
    openlog("sensor_publisher", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handler: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (init_mqtt() != 0) {
        syslog(LOG_ERR, "Failed to initialize MQTT");
        closelog();
        return 1;
    }

    while (running) {
        float temperature, humidity;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_sensor_data(&temperature, &humidity) == 0) {
                success = 1;
                break;
            }
            syslog(LOG_ERR, "Failed to read sensor data (attempt %d/%d)", retries + 1, MAX_RETRIES);
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(1);
            }
        }

        if (success) {
            if (publish_sensor_data(temperature, humidity) != 0) {
                syslog(LOG_ERR, "Failed to publish sensor data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read sensor data after %d attempts", MAX_RETRIES);
        }

        if (running) {
            sleep(READ_INTERVAL_SEC);
        }
    }

    cleanup();
    return 0;
}

