#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <pthread.h>
#include <syslog.h>
#include <syslog.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_sensor"
#define MQTT_TOPIC "sensor_data"
#define SENSOR_READ_INTERVAL 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static MQTTClient client;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_mqtt(void) {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                          MQTTCLIENT_PERSISTENCE_NONE, NULL) != MQTTClient_create_OK) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", strerror(errno));
        return -1;
    }

    if (MQTTClient_connect(&client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", MQTTClient_strerror(&client));
        MQTTClient_destroy(&client);
        return -1;
    }

    syslog(LOG_INFO, "Connected to MQTT broker: %s", MQTT_BROKER_ADDRESS);
    return 0;
}

static int publish_sensor_data(const char *topic, const char *data) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = (void *)data;
    pubmsg.payloadlen = (int)strlen(data);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(&client, topic, &pubmsg, &token);

    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", MQTTClient_strerror(&client));
        return -1;
    }

    syslog(LOG_INFO, "Published: %s", data);
    return 0;
}

static int read_sensor_data(float *temperature, float *humidity) {
    *temperature = 25.0f;
    *humidity = 50.0f;
    return 0;
}

static void cleanup(void) {
    if (client != NULL) {
        MQTTClient_disconnect(&client, 1000);
        MQTTClient_destroy(&client);
        syslog(LOG_INFO, "MQTT client destroyed");
    }
    pthread_mutex_destroy(&mutex);
    closelog();
}

int main(void) {
    openlog("sensor_publisher", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (init_mqtt() != 0) {
        syslog(LOG_ERR, "Failed to initialize MQTT");
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        float temperature, humidity;
        if (read_sensor_data(&temperature, &humidity) != 0) {
            syslog(LOG_ERR, "Failed to read sensor data");
        } else {
            char data[64];
            snprintf(data, sizeof(data), "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);
            if (publish_sensor_data(MQTT_TOPIC, data) != 0) {
                syslog(LOG_ERR, "Failed to publish sensor data");
            }
        }
        sleep(SENSOR_READ_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

