#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_DUTY 500
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or not running?).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, PWM_DUTY) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for pin %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        printf("PWM duty cycle: %d\n", PWM_DUTY);
        fflush(stdout);
        sleep(POLL_INTERVAL);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define CHIP_NAME   "gpiochip0"
#define MAX_RETRIES 5
#define POLL_INTERVAL_US 200000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(struct gpiod_line *trig) {
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trigger high)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trigger low)");
        return -1;
    }
    return 0;
}

static int read_echo(struct gpiod_line *echo) {
    int val = gpiod_line_get_value(echo);
    if (val < 0) {
        perror("gpiod_line_get_value(echo)");
        return -1;
    }
    return val;
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (trigger_sensor(trig) < 0) return -1.0f;
        usleep(50000);
        int echo_val = read_echo(echo);
        if (echo_val < 0) return -1.0f;
        if (echo_val == 0) return -1.0f;
        int timeout = 0;
        while (gpiod_line_get_value(echo) == 1 && timeout < 100000) {
            usleep(1);
            timeout++;
        }
        if (timeout >= 100000) return -1.0f;
        int duration = 0;
        while (gpiod_line_get_value(echo) == 0 && duration < 100000) {
            usleep(1);
            duration++;
        }
        if (duration >= 100000) return -1.0f;
        float distance = (duration * 0.0343f);
        return distance;
    }
    return -1.0f;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        float distance = measure_distance(trig, echo);
        if (distance < 0.0f) {
            fprintf(stderr, "Error: HC-SR04 measurement failed after %d retries.\n", MAX_RETRIES);
            break;
        }
        printf("Distance: %.2f cm\n", distance);
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
