        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM1, PWM2, PWM3, PWM4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
