#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    struct timeval tv;
    struct tm tm_info;
    if (gettimeofday(&tv, NULL) != 0) {
        return -1;
    }
    if (localtime_r(&tv.tv_sec, &tm_info) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        return -1;
    }
    size_t pos = strlen(buf);
    if (snprintf(buf + pos, len - pos, ".%03ld", tv.tv_usec / 1000) < 0) {
        return -1;
    }
    return 0;
}

static int publish_sensor_data(const char *topic, const char *message) {
    MQTTClient client;
    int rc;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        rc = MQTTClient_connect(client, MQTT_HOST, MQTT_PORT, MQTT_CLIENT_ID, MQTT_KEEPALIVE, MQTT_TIMEOUT);
        if (rc == MQTTCLIENT_SUCCESS) {
            rc = MQTTClient_publishMessage(client, topic, message, MQTT_QOS);
            if (rc == MQTTCLIENT_SUCCESS) {
                MQTTClient_disconnect(client, MQTT_TIMEOUT);
                return 0;
            } else {
                syslog(LOG_ERR, "Failed to publish message: %s", MQTTClient_strerror(rc));
            }
        } else {
            syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", MQTTClient_strerror(rc));
        }
        retries++;
        sleep(1);
    }
    syslog(LOG_ERR, "Failed to connect to MQTT broker after %d retries", MAX_RETRIES);
    return -1;
}

int main(void) {
    openlog("sensor_publisher", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    MQTTClient client;
    int rc;

    rc = MQTTClient_create(&client, MQTT_HOST, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", MQTTClient_strerror(rc));
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        char timestamp[32];
        if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
            syslog(LOG_ERR, "Failed to get timestamp: %s", strerror(errno));
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        char message[128];
        snprintf(message, sizeof(message), "%s: Sensor Reading", timestamp);

        if (publish_sensor_data(MQTT_TOPIC, message) != 0) {
            syslog(LOG_ERR, "Failed to publish sensor data");
        }

        sleep(READ_INTERVAL_SEC);
    }

    MQTTClient_destroy(&client);
    closelog();
    return EXIT_SUCCESS;
}

#include <stdio.h>
