#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL, *line18 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line 17");
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line 18");
        goto cleanup;
    }

    if (gpiod_line_request_output(line17, "gpio17", 0) < 0) {
        perror("gpiod_line_request_output 17");
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, "gpio18", 0) < 0) {
        perror("gpiod_line_request_output 18");
        goto cleanup;
    }

    while (keep_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0) {
            perror("gpiod_line_get_value 17");
            break;
        }
        if (val18 < 0) {
            perror("gpiod_line_get_value 18");
            break;
        }

        printf("GPIO 17: %d, GPIO 18: %d\n", val17, val18);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "gpio_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d output started. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_LINE, val);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nGPIO %d output stopped.\n", GPIO_LINE);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_17 17
#define GPIO_23 23

static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line23 = NULL;
static struct gpiod_chip *chip = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line17) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (line23) {
        gpiod_line_release(line23);
        line23 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line23) {
        perror("gpiod_chip_get_line 23");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line17, "gpio17", 0) < 0) {
        perror("gpiod_line_request_output 17");
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line23, "gpio23", 0) < 0) {
        perror("gpiod_line_request_output 23");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO 17 and GPIO 23 set as outputs. Press Ctrl+C to exit.\n");

    while (1) {
        gpiod_line_set_value(line17, 1);
        gpiod_line_set_value(line23, 0);
        printf("GPIO 17: HIGH, GPIO 23: LOW\n");
        sleep(1);
        gpiod_line_set_value(line17, 0);
        gpiod_line_set_value(line23, 1);
        printf("GPIO 17: LOW, GPIO 23: HIGH\n");
        sleep(1);
    }

    cleanup_and_exit(0);
    return 0;
}

