#include <stdio.h>
#include <stdlib.h>
#include <termios.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define PORT "/dev/ttyS0"
#define BAUD_RATE B115200

int main() {
    int fd;
    struct termios options;

    fd = open(PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening serial port");
        return EXIT_FAILURE;
    }

    if (tcgetattr(fd, &options) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);

    options.c_cflag = (options.c_cflag & ~CSIZE) | CS8;
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~(PARENB | PARODD);
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CRTSCTS;

    options.c_iflag = 0;
    options.c_oflag = 0;
    options.c_lflag = 0;

    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &options) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Serial communication started on %s at 115200 baud.\n", PORT);

    while (1) {
        char buffer[256];
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("Error reading from serial port");
            break;
        }
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

int main(void) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Wake up MPU6050 (clear sleep bit)
    if (write(fd, (uint8_t[]){PWR_MGMT_1}, 1) != 1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(100000); // 100 ms stabilization

    while (1) {
        uint8_t buf[6];
        if (read(fd, buf, 6) != 6) {
            fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        fflush(stdout);

        usleep(100000); // 100 ms
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define BMP280_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

static int32_t dig_T1, dig_T2, dig_T3;
static int32_t dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
static int32_t t_fine;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int read_calibration(int fd) {
    uint8_t cal[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, cal, 24) < 0) return -1;
    dig_T1 = (cal[1] << 8) | cal[0];
    dig_T2 = (cal[3] << 8) | cal[2];
    dig_T3 = (cal[5] << 8) | cal[4];
    dig_P1 = (cal[7] << 8) | cal[6];
    dig_P2 = (cal[9] << 8) | cal[8];
    dig_P3 = (cal[11] << 8) | cal[10];
    dig_P4 = (cal[13] << 8) | cal[12];
    dig_P5 = (cal[15] << 8) | cal[14];
    dig_P6 = (cal[17] << 8) | cal[16];
    dig_P7 = (cal[19] << 8) | cal[18];
    dig_P8 = (cal[21] << 8) | cal[20];
    dig_P9 = (cal[23] << 8) | cal[22];
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)dig_T1)) * ((adc_T >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int32_t var1, var2;
    uint32_t p;
    var1 = (((int32_t)t_fine) >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)dig_P6);
    var2 = var2 + ((var1 * ((int32_t)dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)dig_P4) << 16);
    var1 = (((dig_P3 * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) + ((((int32_t)dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)dig_P1)) >> 15);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1048576 - adc_P) - (var2 >> 12))) * 3125));
    if (p == 0) return 0;
    p = (p * 6250) / (uint32_t)var1;
    var1 = (((int32_t)dig_P9) * (int32_t)((p >> 3) * (p >> 3))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + dig_P7) >> 4));
    return p;
}

static int read_bmp280(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;
    int32_t adc_P = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t adc_T = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t t = compensate_temperature(adc_T);
    *temperature = t / 100.0f;
    uint32_t p = compensate_pressure(adc_P);
    *pressure = p / 100.0f;
    return 0;
}

int main(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BMP280_ADDR, strerror(errno));
        close(fd);
        return 1;
    }
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error reading BMP280 ID: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (id != 0x58) {
        fprintf(stderr, "Error: BMP280 not found (ID=0x%02X, expected 0x58)\n", id);
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting BMP280: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    usleep(2000);
    if (read_calibration(fd) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing CTRL_MEAS: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error writing CONFIG: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    while (1) {
        float temperature, pressure;
        if (read_bmp280(fd, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Error reading BMP280 data: %s\n", strerror(errno));
        }
        sleep(5);
    }
    close(fd);
    return 0;
}

#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>

#define PWM_PIN 4

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or not running?)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* pigpio hardware PWM range is 0-255; keep value within this range */
    if (gpioPWM(PWM_PIN, 128) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM output started on GPIO %d (range 0-255)\n", PWM_PIN);
    fflush(stdout);

    /* Keep running; pigpio will handle the loop */
    while (1) {
        gpioDelay(100000); /* 100 ms */
    }

    /* Unnecessary but safe: stop PWM and terminate */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13
#define CONSUMER "gpio_test"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line5 = NULL;
static struct gpiod_line *line6 = NULL;
static struct gpiod_line *line13 = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line5) gpiod_line_release(line5);
    if (line6) gpiod_line_release(line6);
    if (line13) gpiod_line_release(line13);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return 1;
    }

    line5 = gpiod_chip_get_line(chip, GPIO_5);
    line6 = gpiod_chip_get_line(chip, GPIO_6);
    line13 = gpiod_chip_get_line(chip, GPIO_13);
    if (!line5 || !line6 || !line13) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(0);
    }

    if (gpiod_line_request_output(line5, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line6, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line13, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(0);
    }

    printf("GPIO 5, 6, 13 set as output. Press Ctrl+C to exit.\n");

    while (1) {
        gpiod_line_set_value(line5, 1);
        gpiod_line_set_value(line6, 0);
        gpiod_line_set_value(line13, 1);
        printf("GPIO 5=1, GPIO 6=0, GPIO 13=1\n");
        sleep(1);
    }

    cleanup_and_exit(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <syslog.h>
#include <pthread.h>
#include <mqttc.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "rpi_sensor"
#define MQTT_KEEPALIVE 60
#define MQTT_QOS 1

static volatile sig_atomic_t running = 1;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int publish_sensor_data(const char *topic, const char *message) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    rc = MQTTClient_create(&client, MQTT_HOST, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", strerror(errno));
        return -1;
    }

    conn_opts.keepAliveInterval = MQTT_KEEPALIVE;
    conn_opts.cleansession = 1;
    conn_opts.connectTimeout = 10;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", strerror(errno));
        MQTTClient_destroy(&client);
        return -1;
    }

    rc = MQTTClient_setCallback(client, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to set callback: %s", strerror(errno));
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return -1;
    }

    rc = MQTTClient_publishMessage(client, topic, message, MQTT_QOS);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", strerror(errno));
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return -1;
    }

    rc = MQTTClient_disconnect(client, 1000);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to disconnect: %s", strerror(errno));
    }

    MQTTClient_destroy(&client);
    return 0;
}

int main(void) {
    openlog("sensor_publisher", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];
        char message[256];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        if (timeinfo == NULL) {
            syslog(LOG_ERR, "Failed to get local time: %s", strerror(errno));
            sleep(1);
            continue;
        }

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        snprintf(message, sizeof(message), "{\"sensor1\": %ld, \"sensor2\": %ld, \"timestamp\": \"%s\"}",
                 (long)time(NULL), (long)time(NULL), timestamp);

        pthread_mutex_lock(&mutex);
        if (publish_sensor_data(MQTT_TOPIC, message) != 0) {
            syslog(LOG_ERR, "Failed to publish sensor data");
        }
        pthread_mutex_unlock(&mutex);

        sleep(1);
    }

    syslog(LOG_INFO, "Shutting down gracefully...");
    closelog();
    return EXIT_SUCCESS;
}

#include <pigpio.h>
