    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM1, PWM2, PWM3, PWM4, PWM5};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) != 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM pins initialized: GPIO %d, %d, %d, %d, %d\n", PWM1, PWM2, PWM3, PWM4, PWM5);
    printf("Press Ctrl+C to exit.\n");

    while (1) {
        printf("PWM pins: GPIO %d=%d, %d=%d, %d=%d, %d=%d, %d=%d\n",
