#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define CONSUMER "dht22-reader"

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int wait_for_line(struct gpiod_line *line, int val, int timeout_ms) {
    int elapsed = 0;
    while (elapsed < timeout_ms) {
        int v = gpiod_line_get_value(line);
        if (v < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (v == val) return 0;
        usleep(1000);
        elapsed += 1000;
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    unsigned char data[5] = {0, 0, 0, 0, 0};
    int i;

    if (gpiod_line_request_output(line, CONSUMER, 1) < 0) {
        fprintf(stderr, "Failed to request line as output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set line low: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set line high: %s\n", strerror(errno));
        return -1;
    }
    usleep(30);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set line low: %s\n", strerror(errno));
        return -1;
    }

    if (wait_for_line(line, 0, 100) < 0) return -1;
    if (wait_for_line(line, 1, 100) < 0) return -1;
    if (wait_for_line(line, 0, 100) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_line(line, 1, 100) < 0) return -1;
        if (wait_for_line(line, 0, 100) < 0) return -1;
    }

    for (i = 0; i < 40; i++) {
        int high_us = wait_for_line(line, 1, 100);
        if (high_us < 0) return -1;
        int low_us = wait_for_line(line, 0, 100);
        if (low_us < 0) return -1;
        data[i / 8] <<= 1;
        if (high_us > 50) data[i / 8] |= 1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *humidity = (float)(((data[0] << 8) + data[1]) / 10.0);
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;
    int ret = 1;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", DHT22_PIN, strerror(errno));
        goto cleanup;
    }

    while (keep_running) {
        if (read_dht22(line, &temperature, &humidity) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
            ret = 0;
        } else {
            fprintf(stderr, "Failed to read DHT22\n");
        }
        sleep(5);
    }

    ret = 0;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

