int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char tx_buf[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx_buf[3] = {0};

    if (gpioWrite(0, 0) < 0) {
        syslog(LOG_ERR, "Failed to set MCP3008 channel select: %s", strerror(errno));
        return -1;
    }
    if (gpioWrite(1, 1) < 0) {
        syslog(LOG_ERR, "Failed to set MCP3008 start conversion: %s", strerror(errno));
        return -1;
    }

    gpioDelay(1000);

    if (gpioWrite(1, 0) < 0) {
        syslog(LOG_ERR, "Failed to set MCP3008 end conversion: %s", strerror(errno));
        return -1;
    }

    int bytes = spiRead(0, (char *)tx_buf, (char *)rx_buf, 3);
    if (bytes != 3) {
        syslog(LOG_ERR, "SPI read failed: expected 3 bytes, got %d", bytes);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

int publish_mqtt(const char *message) {
    int rc = MQTTClient_publishMessage(&client, MQTT_TOPIC, message, MQTTQOS_0);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

void cleanup() {
    if (pigpio_initialized) {
        spiClose(0);
        gpioTerminate();
        pigpio_initialized = 0;
    }
    if (client != NULL) {
        MQTTClient_destroy(&client);
    }
    closelog();
}

int main() {
    openlog("sensor_reader", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed: %s", strerror(errno));
        closelog();
        return 1;
    }
    pigpio_initialized = 1;

    if (spiOpen(0, 1000000, 0) < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTTCLIENT_PERSISTENCE_NONE, NULL) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT client creation failed");
        cleanup();
        return 1;
    }

    if (MQTTClient_connect(&client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed");
        cleanup();
        return 1;
    }

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read MCP3008");
        } else {
            char message[64];
            snprintf(message, sizeof(message), "ADC: %d", adc_value);
            if (publish_mqtt(message) != 0) {
                syslog(LOG_ERR, "Failed to publish MQTT message");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_BUFFER_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3)

static int fd = -1;

static int xioctl(int fh, int request, void *arg) {
    int r;
    do {
        r = ioctl(fh, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffer = NULL;
    int i;

    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", CAMERA_DEVICE, strerror(errno));
        return -1;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", CAMERA_DEVICE);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", CAMERA_DEVICE);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    buffer = malloc(buf.length);
    if (!buffer) {
        fprintf(stderr, "Error allocating buffer: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        free(buffer);
        close(fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        free(buffer);
        close(fd);
        return -1;
    }

    return 0;
}

static int capture_image(void) {
    struct v4l2_buffer buf;
    unsigned char *image = NULL;
    int ret;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    ret = xioctl(fd, VIDIOC_DQBUF, &buf);
    if (ret < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    image = malloc(buf.length);
    if (!image) {
        fprintf(stderr, "Error allocating image buffer: %s\n", strerror(errno));
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    memcpy(image, buffer, buf.length);

    ret = xioctl(fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        free(image);
        return -1;
    }

    return 0;
}

static int save_image(const char *filename, const unsigned char *image, int width, int height) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t bytes_written = fwrite(image, 1, (size_t)width * height * 3, fp);
    if (bytes_written != (size_t)width * height * 3) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (init_camera() < 0) {
        return EXIT_FAILURE;
    }

    if (capture_image() < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (save_image("image.jpg", buffer, IMAGE_WIDTH, IMAGE_HEIGHT) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    close(fd);
    free(buffer);
    return EXIT_SUCCESS;
}

