    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM3, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM4, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM5, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM6, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 6; i++) {
        if (gpioPWM(PWM1, 128) != 0 ||
            gpioPWM(PWM2, 128) != 0 ||
            gpioPWM(PWM3, 128) != 0 ||
            gpioPWM(PWM4, 128) != 0 ||
            gpioPWM(PWM5, 128) != 0 ||
            gpioPWM(PWM6, 128) != 0) {
