#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_pulse(struct gpiod_line *trig) {
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    return 0;
}

static int wait_for_echo(struct gpiod_line *echo, int timeout_us) {
    int elapsed = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (elapsed >= timeout_us) return -1;
        usleep(1);
        elapsed++;
    }
    while (gpiod_line_get_value(echo) == 1) {
        if (elapsed >= timeout_us) return -1;
        usleep(1);
        elapsed++;
    }
    return elapsed;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    printf("HC-SR04 reader started (libgpiod). Press Ctrl+C to exit.\n");

    while (running) {
        int retries = 0;
        int val = -1;

        while (retries < MAX_RETRIES && running) {
            if (trigger_pulse(trig) < 0) {
                fprintf(stderr, "Trigger pulse failed\n");
                retries++;
                continue;
            }
            int t0 = wait_for_echo(echo, 100000);
            if (t0 < 0) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                retries++;
                continue;
            }
            int t1 = wait_for_echo(echo, 100000);
            if (t1 < 0) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                retries++;
                continue;
            }
            val = t1 - t0;
            break;
        }

        if (val < 0) {
            fprintf(stderr, "HC-SR04 read failed after %d retries\n", MAX_RETRIES);
            goto cleanup;
        }

        printf("Distance: %d mm\n", val);
        sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM1 8
#define PWM2 9
#define PWM3 11
#define PWM4 18

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM3, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM1, PWM2, PWM3, PWM4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetPWMrange(pins[i], 100) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (gpioPWM(pins[i], 50) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM: GPIO %d=%d, GPIO %d=%d, GPIO %d=%d, GPIO %d=%d\n",
               PWM1, 50, PWM2, 50, PWM3, 50, PWM4, 50);
        fflush(stdout);
        sleep(1);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_FRAME_RATE 30
#define CAPTURE_INTERVAL_US 100000
#define MAX_RETRIES 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    int fd = -1;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = CAPTURE_WIDTH;
    fmt.fmt.pix.height = CAPTURE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct v4l2_buffer *buf_ptr = malloc(sizeof(struct v4l2_buffer));
    if (!buf_ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        close(fd);
        return -1;
    }
    buf_ptr->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf_ptr->memory = V4L2_MEMORY_MMAP;
    buf_ptr->index = 0;

    if (xioctl(fd, VIDIOC_QBUF, buf_ptr) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        free(buf_ptr);
        close(fd);
        return -1;
    }

    fd = -1;
    return fd;
}

static int capture_image(int fd, const char *filename) {
    struct v4l2_buffer buf;
    struct v4l2_buffer *buf_ptr = NULL;
    int ret = -1;

    buf_ptr = malloc(sizeof(struct v4l2_buffer));
    if (!buf_ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    buf_ptr->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf_ptr->memory = V4L2_MEMORY_MMAP;
    buf_ptr->index = 0;

    if (xioctl(fd, VIDIOC_DQBUF, buf_ptr) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        free(buf_ptr);
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        xioctl(fd, VIDIOC_QBUF, buf_ptr);
        free(buf_ptr);
        return -1;
    }

    unsigned char *image_data = malloc(CAPTURE_WIDTH * CAPTURE_HEIGHT);
    if (!image_data) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(fp);
        xioctl(fd, VIDIOC_QBUF, buf_ptr);
        free(buf_ptr);
        return -1;
    }

    for (int i = 0; i < CAPTURE_WIDTH * CAPTURE_HEIGHT; i++) {
        image_data[i] = 0xFF;
    }

    if (fwrite(image_data, 1, CAPTURE_WIDTH * CAPTURE_HEIGHT, fp) != CAPTURE_WIDTH * CAPTURE_HEIGHT) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        free(image_data);
        fclose(fp);
        xioctl(fd, VIDIOC_QBUF, buf_ptr);
        free(buf_ptr);
        return -1;
    }

    free(image_data);
    fclose(fp);

    if (xioctl(fd, VIDIOC_QBUF, buf_ptr) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        free(buf_ptr);
        return -1;
    }

    ret = 0;
    free(buf_ptr);
    return ret;
}

int main(void) {
    int fd = -1;
    int retries = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    while (running) {
        fd = init_camera(&fd);
        if (fd < 0) {
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Failed to initialize camera after %d retries. Exiting.\n", MAX_RETRIES);
                break;
            }
            usleep(CAPTURE_INTERVAL_US);
            continue;
        }

        if (capture_image(fd, "image.jpg") < 0) {
            fprintf(stderr, "Failed to capture image. Exiting.\n");
            break;
        }

        if (xioctl(fd, VIDIOC_STREAMOFF, &fd) < 0) {
            fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        }

        usleep(CAPTURE_INTERVAL_US);
    }

    if (fd >= 0) {
        if (xioctl(fd, VIDIOC_STREAMOFF, &fd) < 0) {
            fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
