#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define PCF8574_ADDR 0x27
#define I2C_DEVICE "/dev/i2c-1"

int main() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", PCF8574_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    // PCF8574 control byte: 1 = enable, 0 = disable
    unsigned char control_byte = 0x01;
    unsigned char data[8] = {0x3F, 0x21, 0x41, 0x45, 0x4B, 0x01, 0x71, 0x31};

    for (int i = 0; i < 8; i++) {
        if (write(fd, &control_byte, 1) != 1) {
            fprintf(stderr, "Error writing control byte: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        if (write(fd, &data[i], 1) != 1) {
            fprintf(stderr, "Error writing data byte: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        usleep(20000); // 20ms delay
    }

    close(fd);
    return 0;
}

