#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define SHT31_ADDR 0x44
#define I2C_DEVICE "/dev/i2c-1"
#define READ_INTERVAL_SEC 5

static int i2c_fd = -1;

static int sht31_read(float *temperature, float *humidity)
{
    uint8_t cmd[2] = {0x2C, 0x06};
    uint8_t data[6];

    if (write(i2c_fd, cmd, 2) != 2) {
        fprintf(stderr, "Error: Failed to write measurement command: %s\n", strerror(errno));
        return -1;
    }

    usleep(10000);

    if (read(i2c_fd, data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read measurement data: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_humidity = (data[0] << 8) | data[1];
    uint16_t raw_temp = (data[3] << 8) | data[4];

    *humidity = (float)raw_humidity / 100.0f;
    *temperature = (float)raw_temp / 10.0f;

    return 0;
}

int main(void)
{
    float temperature, humidity;

    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", SHT31_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (sht31_read(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error: Failed to read SHT31 data.\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    close(i2c_fd);
    return 0;
}

