        }
        printf("GPIO 2=0, GPIO 3=0, GPIO 5=0, GPIO 17=0\n");
        fflush(stdout);

        sleep(5);
    }

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

