#include <stdlib.h>
#include <unistd.h>

#define NUM_PIXELS 3
#define GPIO_PIN 18
#define DELAY_MS 5

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed. Is the pigpio daemon running?\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < NUM_PIXELS; j++) {
            gpioWrite(GPIO_PIN, 1);
            gpioDelay(DELAY_MS * 1000);
            gpioWrite(GPIO_PIN, 0);
            gpioDelay(DELAY_MS * 1000);
        }
    }

    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

