#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define W1_CHIP "/sys/bus/w1/devices"
#define W1_SLAVE "/sys/bus/w1/slaves"
#define W1_DIR "/sys/bus/w1/devices/"
#define W1_ID "28-00000444c6f4"
#define W1_CONSUMER "ds18b20"

static int w1_write(const char *path, const char *value) {
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s", value) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int w1_read(const char *path, char *buf, size_t len) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (!fgets(buf, (int)len, fp)) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int read_temperature(void) {
    char path[256];
    char value[32];
    int ret;

    snprintf(path, sizeof(path), "%s/%s/w1_slave", W1_DIR, W1_ID);

    ret = w1_write(path, "1");
    if (ret) return -1;

    usleep(100000);

    ret = w1_read(path, value, sizeof(value));
    if (ret) return -1;

    if (strstr(value, "YES") == NULL) {
        fprintf(stderr, "Error: DS18B20 not responding (no 'YES' in response)\n");
        return -1;
    }

    char *temp_str = strstr(value, "t=");
    if (!temp_str) {
        fprintf(stderr, "Error: Temperature data not found in response\n");
        return -1;
    }

    errno = 0;
    long millideg = strtol(temp_str + 2, NULL, 10);
    if (errno != 0) {
        fprintf(stderr, "Error: Failed to parse temperature value\n");
        return -1;
    }

    return (int)(millideg / 1000);
}

int main(void) {
    int ret;
    int exit_code = 0;

    for (int i = 0; i < 3 && exit_code == 0; i++) {
        printf("Reading %d...\n", i + 1);
        ret = read_temperature();
        if (ret < 0) {
            fprintf(stderr, "Error reading temperature, exiting.\n");
            exit_code = 1;
            break;
        }
        printf("Temperature: %d C\n", ret);
        sleep(5);
    }

    if (exit_code == 0) {
        printf("Cleaning up...\n");
        char path[256];
        snprintf(path, sizeof(path), "%s/%s", W1_CHIP, W1_SLAVE);
        w1_write(path, "0");
    }

    return exit_code;
}

