#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIG_PIN 18
#define ECHO_PIN 23
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(struct gpiod_line *trig) {
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trig HIGH)");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig LOW)");
        return -1;
    }
    return 0;
}

static int read_echo(struct gpiod_line *echo) {
    int val = gpiod_line_get_value(echo);
    if (val < 0) {
        perror("gpiod_line_get_value(echo)");
        return -1;
    }
    return val;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor(trig) < 0) {
            break;
        }

        int echo_val = read_echo(echo);
        if (echo_val < 0) {
            break;
        }

        if (echo_val == 1) {
            printf("Echo HIGH (object detected) - %d\n", echo_val);
        } else {
            printf("Echo LOW (no object) - %d\n", echo_val);
        }

        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

