#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM1 4
#define PWM2 17
#define PWM3 18
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    if (gpioSetMode(PWM1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int state1 = gpioRead(PWM1);
        int state2 = gpioRead(PWM2);
        int state3 = gpioRead(PWM3);

        if (state1 < 0 || state2 < 0 || state3 < 0) {
            fprintf(stderr, "Error: GPIO read failed (PWM1=%d, PWM2=%d, PWM3=%d)\n",
                    state1, state2, state3);
            break;
        }

        printf("PWM1: %d, PWM2: %d, PWM3: %d\n", state1, state2, state3);
        fflush(stdout);

        usleep(SAMPLE_INTERVAL_US);
    }

    gpioWrite(PWM1, 0);
    gpioWrite(PWM2, 0);
    gpioWrite(PWM3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

