#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define NUM_READINGS 3
#define CONSUMER "dht22_reader"

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int i;

    // Send start signal: pull low for 1ms, then high for 30us
    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) return -1;
    gpiod_line_set_value(line, 0);
    usleep(1000);
    gpiod_line_set_value(line, 1);
    usleep(30);
    gpiod_line_set_value(line, 0);

    // Switch to input with pull-up
    if (gpiod_line_request_input(line, CONSUMER) < 0) return -1;

    // Wait for sensor response: low for 80us, then high for 80us
    int timeout = 0;
    while (gpiod_line_get_value(line) == 1) {
        usleep(1);
        timeout++;
        if (timeout > 100) return -1;
    }
    timeout = 0;
    while (gpiod_line_get_value(line) == 0) {
        usleep(1);
        timeout++;
        if (timeout > 100) return -1;
    }
    timeout = 0;
    while (gpiod_line_get_value(line) == 1) {
        usleep(1);
        timeout++;
        if (timeout > 100) return -1;
    }

    // Read 40 bits
    for (i = 0; i < 40; i++) {
        // Wait for low-to-high transition (end of low pulse)
        timeout = 0;
        while (gpiod_line_get_value(line) == 0) {
            usleep(1);
            timeout++;
            if (timeout > 100) return -1;
        }
        // Measure high pulse width
        timeout = 0;
        while (gpiod_line_get_value(line) == 1) {
            usleep(1);
            timeout++;
            if (timeout > 100) return -1;
        }
        int pulse_width = timeout;
        // Convert to bit value: 26us = '0', 70us = '1'
        data[i / 8] <<= 1;
        if (pulse_width > 50) {
            data[i / 8] |= 1;
        }
    }

    // Verify checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -1;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    float temperature, humidity;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    while (keep_running) {
        ret = read_dht22(line, &temperature, &humidity);
        if (ret == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read DHT22 (error %d)\n", ret);
        }
        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    printf("Program finished.\n");
    return 0;
}

