#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN_1 4
#define DHT22_PIN_2 17
#define NUM_READINGS 3
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int i, j;
    struct timespec ts_start, ts_end;
    long elapsed_ms;

    // Send start signal: pull low for 1ms, then high for 30us
    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    gpiod_line_set_value(line, 0);
    usleep(1000);
    gpiod_line_set_value(line, 1);
    usleep(30);
    gpiod_line_set_value(line, 0);

    // Switch to input with pull-up
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;
    gpiod_line_set_config(line, GPIOD_LINE_REQUEST_DIRECTION_INPUT, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);

    // Wait for sensor response: low for 80us, high for 80us
    ts_start = clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (gpiod_line_get_value(line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts_end) < 0) return -1;
        elapsed_ms = (ts_end.tv_sec - ts_start.tv_sec) * 1000 + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000000;
        if (elapsed_ms > POLL_TIMEOUT_MS) return -1;
    }
    ts_start = clock_gettime(CLOCK_MONOTONON, &ts_start);
    while (gpiod_line_get_value(line) == 0) {
        if (clock_gettime(CLOCK_MONOTONON, &ts_end) < 0) return -1;
        elapsed_ms = (ts_end.tv_sec - ts_start.tv_sec) * 1000 + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000000;
        if (elapsed_ms > POLL_TIMEOUT_MS) return -1;
    }
    ts_start = clock_gettime(CLOCK_MONOTONON, &ts_start);
    while (gpiod_line_get_value(line) == 1) {
        if (clock_gettime(CLOCK_MONOTONON, &ts_end) < 0) return -1;
        elapsed_ms = (ts_end.tv_sec - ts_start.tv_sec) * 1000 + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000000;
        if (elapsed_ms > POLL_TIMEOUT_MS) return -1;
    }

    // Read 40 bits
    for (i = 0; i < 40; i++) {
        // Wait for low-to-high transition (end of low pulse)
        ts_start = clock_gettime(CLOCK_MONOTONON, &ts_start);
        while (gpiod_line_get_value(line) == 0) {
            if (clock_gettime(CLOCK_MONOTONON, &ts_end) < 0) return -1;
            elapsed_ms = (ts_end.tv_sec - ts_start.tv_sec) * 1000 + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000000;
            if (elapsed_ms > POLL_TIMEOUT_MS) return -1;
        }
        // Measure high pulse width
        ts_start = clock_gettime(CLOCK_MONOTONON, &ts_start);
        while (gpiod_line_get_value(line) == 1) {
            if (clock_gettime(CLOCK_MONOTONON, &ts_end) < 0) return -1;
            elapsed_ms = (ts_end.tv_sec - ts_start.tv_sec) * 1000 + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000000;
            if (elapsed_ms > POLL_TIMEOUT_MS) return -1;
        }
        ts_start = clock_gettime(CLOCK_MONOTONON, &ts_start);
        while (gpiod_line_get_value(line) == 0) {
            if (clock_gettime(CLOCK_MONOTONON, &ts_end) < 0) return -1;
            elapsed_ms = (ts_end.tv_sec - ts_start.tv_sec) * 1000 + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000000;
            if (elapsed_ms > POLL_TIMEOUT_MS) return -1;
        }
        long pulse_width = (ts_end.tv_sec - ts_start.tv_sec) * 1000 + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000000;

        // Determine bit value based on pulse width
        if (pulse_width > 50) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -1;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    float temperature, humidity;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, DHT22_PIN_1);
    line2 = gpiod_chip_get_line(chip, DHT22_PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    while (keep_running) {
        int valid_readings = 0;
        for (int i = 0; i < NUM_READINGS; i++) {
            ret = read_dht22(line1, &temperature, &humidity);
            if (ret == 0) {
                printf("Reading %d: Temperature = %.1f C, Humidity = %.1f %%\n", i + 1, temperature, humidity);
                valid_readings++;
            } else {
                fprintf(stderr, "Error reading DHT22 (attempt %d)\n", i + 1);
            }
            sleep(1);
        }

        if (valid_readings == NUM_READINGS) {
            printf("All %d readings valid.\n", NUM_READINGS);
        } else {
            fprintf(stderr, "Not all %d readings valid.\n", NUM_READINGS);
        }

        // Sleep for 60 seconds, checking for signal every 5 seconds
        for (int i = 0; i < 12 && keep_running; i++) {
            sleep(5);
        }
    }

    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
    printf("Program finished.\n");
    return 0;
}

