#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define PWM1 17
#define PWM2 18
#define PWM3 27

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        printf("PWM1: %d, PWM2: %d, PWM3: %d\n",
               gpioGetPWMdutycycle(PWM1),
               gpioGetPWMdutycycle(PWM2),
               gpioGetPWMdutycycle(PWM3));
        fflush(stdout);
        sleep(1);
    }

    gpioPWM(PWM1, 0);
    gpioPWM(PWM2, 0);
    gpioPWM(PWM3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

