    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    echo2 = gpiod_chip_get_line(chip, ECHO_PIN2);
    echo3 = gpiod_chip_get_line(chip, ECHO_PIN3);
    if (!trig || !echo || !echo2 || !echo3) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(trig, "hcsr04", 0);
    if (ret < 0) { perror("gpiod_line_request_output trig"); gpiod_chip_close(chip); return EXIT_FAILURE; }

    ret = gpiod_line_request_input(echo, "hcsr04");
    if (ret < 0) { perror("gpiod_line_request_input echo"); gpiod_chip_close(chip); return EXIT_FAILURE; }

    ret = gpiod_line_request_input(echo2, "hcsr04");
    if (ret < 0) { perror("gpiod_line_request_input echo2"); gpiod_chip_close(chip); return EXIT_FAILURE; }

    ret = gpiod_line_request_input(echo3, "hcsr04");
    if (ret < 0) { perror("gpiod_line_request_input echo3"); gpiod_chip_close(chip); return EXIT_FAILURE; }

    while (running) {
        gpiod_line_set_value(trig, 0);
        usleep(2);
        gpiod_line_set_value(trig, 1);
        usleep(10);
        gpiod_line_set_value(trig, 0);

        int val = gpiod_line_get_value(echo);
        if (val < 0) { perror("gpiod_line_get_value echo"); break; }
        if (val == 0) {
            usleep(100000);
            val = gpiod_line_get_value(echo);
            if (val < 0) { perror("gpiod_line_get_value echo"); break; }
            if (val == 1) {
                int val2 = gpiod_line_get_value(echo2);
                if (val2 < 0) { perror("gpiod_line_get_value echo2"); break; }
                if (val2 == 1) {
                    int val3 = gpiod_line_get_value(echo3);
                    if (val3 < 0) { perror("gpiod_line_get_value echo3"); break; }
                    if (val3 == 1) {
                        printf("Distance: %.2f cm\n", (val2 - val) * 0.0343);
                    }
                }
            }
        }
        usleep(50000);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(echo2);
    gpiod_line_release(echo3);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

