#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define BMP280_ADDR 0x03
#define I2C_BUS "/dev/i2c-1"
#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

static int32_t dig_T1, dig_T2, dig_T3;
static int32_t dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
static int32_t t_fine;

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, BMP280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error: Failed to read BMP280 ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x58 && id != 0xD0) {
        fprintf(stderr, "Error: Invalid BMP280 ID (0x%02X). Expected 0x58 or 0xD0.\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset BMP280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);
    uint8_t calib[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, calib, 24) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }
    dig_T1 = (calib[1] << 8) | calib[0];
    dig_T2 = (calib[3] << 8) | calib[2];
    dig_T3 = (calib[5] << 8) | calib[4];
    dig_P1 = (calib[7] << 8) | calib[6];
    dig_P2 = (calib[9] << 8) | calib[8];
    dig_P3 = (calib[11] << 8) | calib[10];
    dig_P4 = (calib[13] << 8) | calib[12];
    dig_P5 = (calib[15] << 8) | calib[14];
    dig_P6 = (calib[17] << 8) | calib[16];
    dig_P7 = (calib[19] << 8) | calib[18];
    dig_P8 = (calib[21] << 8) | calib[20];
    dig_P9 = (calib[23] << 8) | calib[22];
    if (i2c_write_reg8(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write control register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) {
        fprintf(stderr, "Error: Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }
    int32_t raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t var1 = ((((raw_temperature >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    int32_t var2 = (((((raw_temperature >> 4) - ((int32_t)dig_T1)) * ((raw_temperature >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    t_fine = var1 + var2;
    *temperature = (t_fine * 5 + 128) >> 8;
    *temperature /= 100.0f;
    int64_t v1 = ((int64_t)t_fine) - 128000;
    int64_t v2 = v1 * v1 * (int64_t)dig_P6;
    v2 = v2 + ((v1 * (int64_t)dig_P5) << 17);
    v2 = v2 + (((int64_t)dig_P4) << 35);
    v1 = ((v1 * v1 * (int64_t)dig_P3) >> 8) + ((v1 * (int64_t)dig_P2) << 12);
    v1 = (((((int64_t)1) << 47) + v1)) * ((int64_t)dig_P1) >> 33;
    if (v1 == 0) return -1;
    int64_t p = 1048576 - raw_pressure;
    p = (((p << 31) - v2) * 3125) / v1;
    v1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    v2 = (((int64_t)dig_P8) * p) >> 19;
    p = ((p + v1 + v2) >> 8) + (((int64_t)dig_P7) << 4);
    *pressure = (float)p / 256.0f;
    return 0;
}

int main() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", BMP280_ADDR, strerror(errno));
        close(fd);
        return 1;
    }
    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "Error: BMP280 initialization failed.\n");
        close(fd);
        return 1;
    }
    float temperature, pressure;
    for (int i = 0; i < 3; i++) {
        if (bmp280_read(fd, &temperature, &pressure) < 0) {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
            close(fd);
            return 1;
        }
        printf("Reading %d: Temperature = %.2f C, Pressure = %.2f Pa\n", i + 1, temperature, pressure);
        sleep(1);
    }
    close(fd);
    return 0;
}

