#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7

static int fd = -1;

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, BME280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error: Failed to read BME280 ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Error: Invalid BME280 ID: 0x%02X (expected 0x60)\n", id);
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset BME280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    if (i2c_write_reg8(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set humidity oversampling: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error: Failed to set config: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to set control measurement: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bme280_read_data(int fd, float *temperature, float *humidity, float *pressure) {
    uint8_t data[8];
    if (i2c_read_burst(fd, BME280_REG_DATA, data, 8) < 0) {
        fprintf(stderr, "Error: Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    int32_t raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_humidity = (data[6] << 8) | data[7];

    *pressure = (float)raw_pressure / 100.0;
    *temperature = (float)raw_temperature / 100.0;
    *humidity = (float)raw_humidity / 1024.0;
    return 0;
}

int main(void) {
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bme280_init(fd) < 0) {
        fprintf(stderr, "Error: BME280 initialization failed.\n");
        close(fd);
        return 1;
    }

    printf("BME280 initialized successfully.\n");

    for (int i = 0; i < 3; i++) {
        float temperature, humidity, pressure;
        if (bme280_read_data(fd, &temperature, &humidity, &pressure) == 0) {
            printf("Reading %d: Temperature = %.2f C, Humidity = %.2f %%RH, Pressure = %.2f hPa\n", i + 1, temperature, humidity, pressure);
        } else {
            fprintf(stderr, "Error: Failed to read data from BME280.\n");
            close(fd);
            return 1;
        }
        sleep(5);
    }

    close(fd);
    printf("BME280 resources released.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define CONSUMER "gpio_test"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, default value LOW */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_LINE, val);
        fflush(stdout);
        sleep(1);
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    printf("\nGPIO released. Exiting.\n");
    return EXIT_SUCCESS;
}

