#include <errno.h>
#include <string.h>

#define VEML7700_ADDR 0x10
#define I2C_DEVICE "/dev/i2c-1"

static int i2c_fd = -1;

static int veml7700_read(int fd, uint16_t *out) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t raw;
        if (veml7700_read(i2c_fd, &raw) == 0) {
            printf("VEML7700 raw: 0x%04X\n", raw);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed, continuing...\n");
        }
        usleep(500000);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define PORT "/dev/ttyS0"
#define BAUD_RATE B115200
#define READ_SIZE 256
#define LOOP_DELAY_MS 100

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int init_serial(const char *port, speed_t baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_serial(int fd, char *buf, size_t size) {
    ssize_t n = read(fd, buf, size);
    if (n < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) {
        return 0;
    }
    return (int)n;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = init_serial(PORT, BAUD_RATE);
    if (fd < 0) {
        return 1;
    }

    char buf[READ_SIZE];
    while (keep_running) {
        int n = read_serial(fd, buf, sizeof(buf));
        if (n > 0) {
            printf("Received: %s", buf);
            fflush(stdout);
        } else if (n < 0) {
            fprintf(stderr, "Error reading from serial port\n");
            break;
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"
#define POLL_MS     500000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_pulse(struct gpiod_line *trig) {
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    return 0;
}

static int wait_echo(struct gpiod_line *echo, int *timeout_ms) {
    int elapsed = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (elapsed >= *timeout_ms) return -1;
        usleep(10);
        elapsed++;
    }
    while (gpiod_line_get_value(echo) == 1) {
        if (elapsed >= *timeout_ms) return -1;
        usleep(10);
        elapsed++;
    }
    return elapsed;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output trigger");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }

    printf("HC-SR04 reader started (GPIO %d trigger, %d echo). Press Ctrl+C to exit.\n",
           TRIGGER_PIN, ECHO_PIN);

    while (running) {
        if (trigger_pulse(trig) < 0) {
            fprintf(stderr, "Trigger pulse failed\n");
            break;
        }

        int timeout = POLL_MS;
        int duration = wait_echo(echo, &timeout);
        if (duration < 0) {
            fprintf(stderr, "Echo timeout or stuck\n");
            break;
        }

        if (duration == 0) {
            fprintf(stderr, "No echo received (object out of range?)\n");
            break;
        }

        float distance = (duration * 0.0343f) / 2.0f;
        printf("Distance: %.2f cm\n", distance);

        usleep(POLL_MS);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8
#define POLL_INTERVAL_US 1000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio8_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: print state and wait */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_LINE, val);
        fflush(stdout);
        usleep(POLL_INTERVAL_US);
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32

static int fd = -1;

void cleanup(int sig) {
    (void)sig;
    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Set data format register to full resolution, +/- 2g
    uint8_t data_format = 0x0B; // 0x08 for full resolution, 0x00 for +/- 2g
    if (write(fd, &data_format, 1) != 1) {
        perror("Failed to write data format");
        close(fd);
        return 1;
    }

    // Enable measurement
    uint8_t power_ctl = 0x08; // 0x08 = measure bit
    if (write(fd, &power_ctl, 1) != 1) {
        perror("Failed to write power control");
        close(fd);
        return 1;
    }

    // Wait for first measurement to be ready
    usleep(100000); // 100ms

    uint8_t reg = ADXL345_DATAX0;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to set data register");
        close(fd);
        return 1;
    }

    uint8_t buf[6];
    if (read(fd, buf, 6) != 6) {
        perror("Failed to read data");
        close(fd);
        return 1;
    }

    // Combine high and low bytes (little-endian)
    int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z = (int16_t)((buf[5] << 8) | buf[4]);

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);
    close(fd);
    return 0;
}

