        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int state1 = (rand() % PWM_RANGE) + 1;
        int state2 = (rand() % PWM_RANGE) + 1;

        if (gpioPWM(PWM_PIN_1, state1) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_1);
            break;
        }
        if (gpioPWM(PWM_PIN_2, state2) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_2);
            break;
        }

        printf("GPIO 4: %d, GPIO 22: %d\n", state1, state2);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

