#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SOUND_PIN 27

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    struct gpiod_line *sound_line = NULL;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    sound_line = gpiod_chip_get_line(chip, SOUND_PIN);
    if (!trigger_line || !echo_line || !sound_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    ret = gpiod_line_request_output(trigger_line, "hcsr04", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output trigger");
        goto cleanup;
    }

    ret = gpiod_line_request_input(echo_line, "hcsr04");
    if (ret < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }

    ret = gpiod_line_request_input(sound_line, "hcsr04");
    if (ret < 0) {
        perror("gpiod_line_request_input sound");
        goto cleanup;
    }

    while (running) {
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        int timeout = 100000;
        while (gpiod_line_get_value(echo_line) == 0 && timeout > 0) {
            usleep(1);
            timeout--;
        }
        if (timeout == 0) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            break;
        }

        timeout = 100000;
        while (gpiod_line_get_value(echo_line) == 1 && timeout > 0) {
            usleep(1);
            timeout--;
        }
        if (timeout == 0) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            break;
        }

        long pulse_duration = timeout;
        printf("Distance: %.2f cm\n", pulse_duration / 58.0);
        fflush(stdout);

        usleep(50000);
    }

cleanup:
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (sound_line) gpiod_line_release(sound_line);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

