#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CTIME 0x03
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_RDATAH 0x17
#define TCS34725_CDATAH 0x18

static int fd = -1;

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device at reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_byte(fd, TCS34725_ID, &id) < 0) {
        fprintf(stderr, "Failed to read ID register\n");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_byte(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_CTIME, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x03) < 0) return -1;
    return 0;
}

int tcs34725_read_measurement(int fd, uint16_t *clear, uint16_t *rain) {
    if (i2c_read_word(fd, TCS34725_CDATAL, clear) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_RDATAL, rain) < 0) return -1;
    return 0;
}

int main() {
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }
    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(fd);
        return 1;
    }
    printf("TCS34725 initialized successfully\n");
    while (1) {
        uint16_t clear, rain;
        if (tcs34725_read_measurement(fd, &clear, &rain) == 0) {
            printf("Clear: %u, Rain: %u\n", clear, rain);
        } else {
            fprintf(stderr, "Failed to read measurement\n");
        }
        sleep(0.5);
    }
    close(fd);
    return 0;
}

