#define PWM1 2
#define PWM2 3
#define PWM3 18

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or not running?)\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM1, PWM2, PWM3};
    int counts[] = {0, 0, 0};

    while (running) {
        for (int i = 0; i < 3; i++) {
            counts[i] = gpioRead(pins[i]);
        }
