    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    echo2_line = gpiod_chip_get_line(chip, ECHO_PIN2);
    if (!trig_line || !echo_line || !echo2_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    ret = gpiod_line_request_output(trig_line, "hc-sr04-trig", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output trig");
        goto cleanup;
    }

    ret = gpiod_line_request_input(echo_line, "hc-sr04-echo");
    if (ret < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }

    ret = gpiod_line_request_input(echo2_line, "hc-sr04-echo2");
    if (ret < 0) {
        perror("gpiod_line_request_input echo2");
        goto cleanup;
    }

    while (running) {
        ret = gpiod_line_set_value(trig_line, 0);
        if (ret < 0) {
