            while (gpiod_line_get_value(echo_line) == 1 && running && timeout++ < 1000000) {
                usleep(1);
            }
            if (!running) break;
            int echo_val = gpiod_line_get_value(echo_line);
            if (echo_val < 0) {
                perror("gpiod_line_get_value echo");
                break;
