    }

    for (int i = 0; i < 3; i++) {
        gpiod_line_set_value(lines[i], 0);
    }
    gpiod_chip_close(chip);
    printf("GPIOs released. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

int main() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    // Wake up MPU6050 (clear sleep bit)
    if (write(fd, (uint8_t[]){PWR_MGMT_1 & ~0x80}, 1) < 0) {
        fprintf(stderr, "Failed to wake MPU6050: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Allow sensor to stabilize
    usleep(100000);

    while (1) {
        uint8_t buf[6];
        if (read(fd, buf, 6) != 6) {
            fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
            break;
        }

        // Combine high and low bytes (little-endian)
        int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        fflush(stdout);

        sleep(1);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL_MS 600

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "gpio_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        printf("GPIO %d: %d\n", GPIO_LINE, val);
        fflush(stdout);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    printf("\nGPIO released. Exiting.\n");
    return EXIT_SUCCESS;
}
